    runs = []
    for r in range(h):
        n = 0
        for c in range(w + 1):
            if c < w and grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
    for c in range(w):
        n = 0
        for r in range(h + 1):
            if r < h and grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
    size = reduce(gcd, runs)

    r0 = min(r for r, c in large)
    c0 = min(c for r, c in large)
    tiles = {((r-r0)//size, (c-c0)//size) for r, c in large}

    sr = min(r for r, c, _ in colored)
    sc = min(c for r, c, _ in colored)
    points = [(r-sr, c-sc, color) for r, c, color in colored]
    shape = {(r, c) for r, c, _ in points}

